   int[] silver={50,75,0,75,100,0,120,0,150,0,250,0,0,200},tokens={0,0,2,0,0,2,0,3,0,3,0,5,4,0};
   for(int i=0;i<14;i++){var mission=m.missions[i];Check(r,mission.requiredCommanderIDs.SequenceEqual(required[i])&&mission.spintoken==silver[i]&&mission.luckytoken==tokens[i],"Native initializer recipe/reward index"+i);Check(r,u.spawnedItems[i].mission==mission&&u.spawnedItems[i].missionNameText.text==mission.missionName&&!string.IsNullOrEmpty(mission.missionName),"Original row setup mission/name"+i);}
   Check(r,Enumerable.Range(0,14).All(i=>Enumerable.Range(0,3).All(j=>u.spawnedItems[i].commanderIcons[j].sprite==f.hero.HeroCommanders[required[i][j]].icon.sprite&&u.spawnedItems[i].rarityColor[j].color==f.hero.rarityColors[(int)f.hero.HeroCommanders[required[i][j]].Rarity])),"All42 original commander IDs resolve correct distinct icon and rarity color");
   var preserved=m.missions;Call(m,"InitializeMissionsIfEmpty");Check(r,ReferenceEquals(preserved,m.missions),"Prepopulated original mission list preserved");
   bool reuse=true;u.SetupUI(m.missions,m,ref reuse);Check(r,reuse&&u.spawnedItems.Count==14&&u.spawnedItems[0].mission==m.missions[0],"Initialized UI path reuses existing rows");
   f.Party(0,4);m.CheckAllMissions();Check(r,!m.missions[0].isCompleted&&w.Silver==0&&w.token==0,"Missing third required commander yields no reward");
   Check(r,u.spawnedItems[0].commanderChecks[0].activeSelf&&u.spawnedItems[0].commanderChecks[1].activeSelf&&!u.spawnedItems[0].commanderChecks[2].activeSelf,"Unfinished row shows actual present/missing commander checks");
   f.Party(0,0,4);m.CheckAllMissions();Check(r,!m.missions[0].isCompleted,"Duplicate commander does not replace missing distinct ID");
   f.Party(0,4,16);var source=f.hero.HeroCommanders[16];var rarity=source.Rarity;source.Rarity=(WeaponRarity)4;m.CheckAllMissions();Check(r,!m.missions[0].isCompleted,"Mystic rarity is excluded even with matching HeroNum");source.Rarity=rarity;
   GameManager.Level=2;m.CheckAllMissions();Check(r,!m.missions[0].isCompleted&&w.Silver==0,"Level2 gate forbids task reward");
   Call(m,"OnEnable");Check(r,!m.btnMission.activeSelf&&!CommanderMissionManager.UpdateData&&!w.pageAcik&&!u.gameObject.activeSelf,"Original OnEnable hides level2 button, closes UI and clears refresh flag");
   GameManager.Level=3;Call(m,"OnEnable");Check(r,m.btnMission.activeSelf,"Level3 original button threshold");
   PlayerData.TalentStats.SilverIncome=1.5f;m.CheckAllMissions();Check(r,m.missions[0].isCompleted&&m.missions[0].rewardClaimed&&w.Silver==75f,"Complete original recipe automatically rewards50 silver through original1.5 income multiplier");
   Check(r,m.completedRewardtxt.text=="<sprite=\"MeduSprite\" index=7>50"&&m.animCompletedOBJ.activeSelf&&u.spawnedItems[0].missionCheckIcon.gameObject.activeSelf,"Silver completion text uses original base amount, animation and completion check");
   m.CheckAllMissions();Call(m,"GiveReward",m.missions[0]);Check(r,w.Silver==75f,"Repeated check/private reward guard does not pay twice");
   f.ResetProgress();f.Party(1,2,3);m.CheckAllMissions();Check(r,m.missions[2].isCompleted&&m.missions[2].rewardClaimed&&w.token==2&&w.Silver==0,"Original token recipe pays2 battle tokens without silver income multiplier");
   Check(r,m.completedRewardtxt.text=="<sprite=\"MeduSprite3\" index=7>2","Original battle token reward icon/template");
   for(int i=0;i<14;i++){f.ResetProgress();f.Party(required[i]);m.CheckAllMissions();Check(r,m.missions[i].isCompleted&&m.missions[i].rewardClaimed&&w.Silver==silver[i]*1.5f&&w.token==tokens[i]&&m.missions.Count(v=>v.isCompleted)==1,"Execute original recipe"+i+" pays exactly original one-mission reward");}
   f.ResetProgress();f.Party(1,2,3);Set(m,"timerDataRefresh",.3f);CommanderMissionManager.UpdateData=false;Call(m,"Update");Check(r,Get<float>(m,"timerDataRefresh")==.3f&&!m.missions[2].isCompleted,"Idle refresh flag preserves timer and does not evaluate");
   Set(m,"timerDataRefresh",1f);CommanderMissionManager.UpdateData=true;Call(m,"Update");Check(r,w.token==2&&!CommanderMissionManager.UpdateData&&Get<float>(m,"timerDataRefresh")==0f,"Actual Update consumes pending refresh at original threshold and resets timer/flag");
   // Production flag comes from actual existing InventorySlot.UpdateRarityVisual, not direct UI fixture assignment.
   var slot=f.At("ProducerSlot").AddComponent<InventorySlot>();slot.enabled=false;slot.RarityColor=f.At("ProducerSlot/Rarity").AddComponent<SpriteRenderer>();slot.lightSlotParent=f.At("ProducerSlot/Lights").transform;slot.heroController=f.hero;CommanderMissionManager.UpdateData=false;Call(slot,"UpdateRarityVisual");Check(r,CommanderMissionManager.UpdateData,"Actual InventorySlot production method requests task refresh");
   Call(m,"OnEnable");Check(r,m.missions.All(x=>!x.isCompleted&&!x.rewardClaimed)&&!CommanderMissionManager.UpdateData,"Next battle OnEnable resets completion and claim flags");
   f.Party();u.rect.anchoredPosition=new Vector2(12,34);u.ResetPage();Check(r,u.rect.anchoredPosition==Vector2.zero,"Original scroll reset");
   w.pageAcik=true;u.gameObject.SetActive(false);u.Open();Check(r,!u.gameObject.activeSelf&&w.pageAcik,"Open respects existing modal/page gate");
   w.pageAcik=false;float clock=Time.timeScale;u.Open();Check(r,u.gameObject.activeSelf&&w.pageAcik&&Time.timeScale==clock,"Open activates panel and page gate without pausing game clock");u.Close();Check(r,!u.gameObject.activeSelf&&!w.pageAcik&&Time.timeScale==clock,"Close clears modal gate without changing clock");
   var missing=new CommanderMission();u.UpdateMissionStatus(missing);Check(r,!w.pageAcik,"Unknown mission UI lookup returns safely");
   r.observations.Add("Original serialized UI: Top/TopSafe/missions Button.Open; Bottom/PopUps/Gorevler/close Button.Close; no new listeners or scene changes are applied by runtime patch.");
   r.limitations.Add("Isolated actual Unity components and original animation/audio assets. Synthetic20-commanders fixture tests logic; no claim of player-earned mission completion or actual raycast interaction.");
   r.limitations.Add("Synchronous Update test seeds private timer above0.7 only in isolated fixture; natural0.7-second runtime refresh is not asserted here. No ES3 task persistence exists in original selected chain.");
  }
  // Independent executeMethod entry; caller uses -quit. No Editor.Exit in reusable checks.
  public static void RunBatch()
  {
   Result result=RunChecks();
   Debug.Log("CommanderMission independent result="+JsonUtility.ToJson(result,true));
   if(!result.passed)Debug.LogError("CommanderMission independent failed: "+string.Join("; ",result.failures));
  }
  public static Result RunChecks()
  {
   var r=new Result{testRoot=Path.Combine(Path.GetTempPath(),"LuckyForgeCommanderMissionChecks",Guid.NewGuid().ToString("N"))};Directory.CreateDirectory(r.testRoot);Fixture f=null;
   try{f=new Fixture(r);Core(f);}catch(Exception ex){r.failures.Add(ex.ToString());}finally{if(f!=null)f.Dispose();}
   r.passed=r.failures.Count==0;File.WriteAllText(Path.Combine(r.testRoot,"commander-mission-results.json"),JsonUtility.ToJson(r,true));Debug.Log("CommanderMission checks="+r.checks+" passed="+r.passed+" result="+r.testRoot);return r;
  }
 }
